+--
+--  SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
+--
+
+--  Winner tree with the keys at the leaves and one cached winner at every
+--  internal node. Updating a leaf replays only its path to the root.
+
+pragma Assertion_Policy (Ghost          => Ignore,
+                         Pre            => Ignore,
+                         Post           => Ignore,
+                         Assert         => Ignore,
+                         Loop_Invariant => Ignore);
+
+with Heaps.Key_Multisets;
+with Heaps.Models;
+
+package Heaps.Tournament with SPARK_Mode is
+
+   use type Key_Multisets.Multiset;
+
+   subtype Tree_Index_Base is Natural range 0 .. 2 * Max_Capacity - 1;
+   subtype Tree_Index is Tree_Index_Base range 1 .. Tree_Index_Base'Last;
+
+   type Winner_Array is array (Index range <>) of Extended_Index;
+   type Winner_Key_Array is array (Index range <>) of Key_Type;
+
+   type Heap (Capacity : Extended_Index) is record
+      Last        : Extended_Index := 0;
+      Keys        : Key_Array (1 .. Capacity);
+      Winners     : Winner_Array (1 .. Capacity - 1) := [others => 0];
+      Winner_Keys : Winner_Key_Array (1 .. Capacity - 1);
+   end record
+     with Predicate => Last <= Capacity;
+
+   function Leaf_Node (H : Heap; Position : Index) return Tree_Index is
+     (Tree_Index (H.Capacity + Position - 1))
+     with Pre  => Position <= H.Capacity,
+          Post => Leaf_Node'Result in H.Capacity .. 2 * H.Capacity - 1;
+
+   function Position_At (H : Heap; Node : Tree_Index) return Extended_Index is
+     (if Node < H.Capacity then H.Winners (Node)
+      elsif Node - H.Capacity + 1 <= H.Last
+      then Node - H.Capacity + 1
+      else 0)
+     with Ghost,
+          Pre => H.Capacity > 0 and then Node <= 2 * H.Capacity - 1;
+
+   function Key_At (H : Heap; Node : Tree_Index) return Key_Type is
+     (if Node < H.Capacity then H.Winner_Keys (Node)
+      else H.Keys (Node - H.Capacity + 1))
+     with Ghost,
+          Pre => H.Capacity > 0
+                 and then Node <= 2 * H.Capacity - 1
+                 and then Position_At (H, Node) > 0;
+
+   function Node_Valid (H : Heap; Node : Index) return Boolean
+     with Ghost,
+          Pre => H.Capacity > 1 and then Node < H.Capacity;
+
+   function Is_Heap (H : Heap) return Boolean is
+     (for all Node in 1 .. H.Capacity - 1 => Node_Valid (H, Node))
+     with Ghost;
+
+   function Is_Minimum (H : Heap; K : Key_Type) return Boolean is
+     (for all I in 1 .. H.Last => K <= H.Keys (I))
+     with Ghost;
+
+   function Model (H : Heap) return Key_Multisets.Multiset is
+     (Models.Occurrences (H.Keys, H.Last))
+     with Ghost;
+
+   function Size (H : Heap) return Extended_Index is (H.Last);
+
+   function Is_Empty (H : Heap) return Boolean is (H.Last = 0);
+
+   function Is_Full (H : Heap) return Boolean is (H.Last = H.Capacity);
+
+   procedure Clear (H : in out Heap)
+     with Post => Is_Empty (H)
+                  and Is_Heap (H)
+                  and Key_Multisets.Is_Empty (Model (H));
+
+   function Root_Position (H : Heap) return Index is
+     (if H.Capacity = 1 then 1 else H.Winners (1))
+     with Ghost,
+          Pre => not Is_Empty (H) and then Is_Heap (H),
+          Post => Root_Position'Result <= H.Last;
+
+   function Peek_Min (H : Heap) return Key_Type is
+     (if H.Capacity = 1 then H.Keys (1) else H.Winner_Keys (1))
+     with Pre  => not Is_Empty (H) and then Is_Heap (H),
+          Post => Is_Minimum (H, Peek_Min'Result)
+                  and then Peek_Min'Result = H.Keys (Root_Position (H));
+
+   function Min_Of (H : Heap) return Key_Type
+     with Pre  => not Is_Empty (H),
+          Post => Is_Minimum (H, Min_Of'Result)
+                  and then (for some I in 1 .. H.Last =>
+                              Min_Of'Result = H.Keys (I));
+
+   procedure Insert (H : in out Heap; K : Key_Type)
+     with Pre  => not Is_Full (H) and then Is_Heap (H),
+          Post => Is_Heap (H)
+                  and Size (H) = Size (H)'Old + 1
+                  and Model (H) = Key_Multisets.Add (Model (H)'Old, K);
+
+   procedure Meld (Into : in out Heap; From : in out Heap)
+     with Pre  => Is_Heap (Into)
+                  and then Is_Heap (From)
+                  and then Size (From) <= Into.Capacity - Size (Into),
+          Post => Is_Heap (Into)
+                  and Size (Into) = Size (Into)'Old + Size (From)'Old
+                  and Is_Empty (From)
+                  and Model (Into) = Model (Into)'Old + Model (From)'Old;
+   --  Destructive meld. The leaf runs are concatenated and the tournament is
+   --  rebuilt bottom-up in linear time.
+
+   procedure Extract_Min (H : in out Heap; K : out Key_Type)
+     with Pre  => not Is_Empty (H) and then Is_Heap (H),
+          Post => Is_Heap (H)
+                  and Size (H) = Size (H)'Old - 1
+                  and K = Peek_Min (H)'Old
+                  and Is_Minimum (H'Old, K)
+                  and Model (H)'Old = Key_Multisets.Add (Model (H), K);
+
+end Heaps.Tournament;
*** Add File: src/heaps-tournament.adb
+--
+--  SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
+--
+
+pragma Assertion_Policy (Ghost          => Ignore,
+                         Pre            => Ignore,
+                         Post           => Ignore,
+                         Assert         => Ignore,
+                         Loop_Invariant => Ignore);
+
+package body Heaps.Tournament with SPARK_Mode is
+
+   package KM renames Key_Multisets;
+
+   function Node_Valid (H : Heap; Node : Index) return Boolean is
+      Left  : constant Tree_Index := 2 * Node;
+      Right : constant Tree_Index := Left + 1;
+      LP    : constant Extended_Index := Position_At (H, Left);
+      RP    : constant Extended_Index := Position_At (H, Right);
+   begin
+      return
+        (if LP = 0 then
+            (if RP = 0 then H.Winners (Node) = 0
+             else H.Winners (Node) = RP
+                    and then H.Winner_Keys (Node) = Key_At (H, Right))
+         elsif RP = 0 then
+            H.Winners (Node) = LP
+              and then H.Winner_Keys (Node) = Key_At (H, Left)
+         elsif Key_At (H, Left) <= Key_At (H, Right) then
+            H.Winners (Node) = LP
+              and then H.Winner_Keys (Node) = Key_At (H, Left)
+         else
+            H.Winners (Node) = RP
+              and then H.Winner_Keys (Node) = Key_At (H, Right));
+   end Node_Valid;
+
+   function Valid_Except (H : Heap; Bad : Tree_Index_Base) return Boolean is
+     (for all Node in 1 .. H.Capacity - 1 =>
+        (if Node /= Bad then Node_Valid (H, Node)))
+     with Ghost;
+
+   procedure Recompute (H : in out Heap; Node : Index)
+     with Pre  => H.Capacity > 1 and then Node < H.Capacity,
+          Post => Node_Valid (H, Node)
+                  and H.Last = H.Last'Old
+                  and H.Keys = H.Keys'Old
+                  and (for all I in H.Winners'Range =>
+                         (if I /= Node then
+                            H.Winners (I) = H.Winners (I)'Old
+                            and H.Winner_Keys (I) = H.Winner_Keys (I)'Old));
+
+   procedure Recompute (H : in out Heap; Node : Index) is
+      Left  : constant Tree_Index := 2 * Node;
+      Right : constant Tree_Index := Left + 1;
+      LP    : constant Extended_Index := Position_At (H, Left);
+      RP    : constant Extended_Index := Position_At (H, Right);
+   begin
+      if LP = 0 then
+         if RP = 0 then
+            H.Winners (Node) := 0;
+         else
+            H.Winners (Node) := RP;
+            H.Winner_Keys (Node) := Key_At (H, Right);
+         end if;
+      elsif RP = 0 or else Key_At (H, Left) <= Key_At (H, Right) then
+         H.Winners (Node) := LP;
+         H.Winner_Keys (Node) := Key_At (H, Left);
+      else
+         H.Winners (Node) := RP;
+         H.Winner_Keys (Node) := Key_At (H, Right);
+      end if;
+   end Recompute;
+
+   procedure Lemma_Recomputed_Frame
+     (Before, After : Heap; Changed : Index)
+     with Ghost,
+          Pre  => Before.Capacity = After.Capacity
+                  and then Before.Last = After.Last
+                  and then Before.Keys = After.Keys
+                  and then Changed < After.Capacity
+                  and then Node_Valid (After, Changed)
+                  and then Valid_Except (Before, Changed)
+                  and then
+                    (for all I in After.Winners'Range =>
+                       (if I /= Changed then
+                          After.Winners (I) = Before.Winners (I)
+                          and After.Winner_Keys (I) = Before.Winner_Keys (I))),
+          Post => Valid_Except (After, Changed / 2);
+
+   procedure Lemma_Recomputed_Frame
+     (Before, After : Heap; Changed : Index)
+   is
+   begin
+      for Node in 1 .. After.Capacity - 1 loop
+         if Node /= Changed / 2 and then Node /= Changed then
+            pragma Assert (2 * Node /= Changed);
+            pragma Assert (2 * Node + 1 /= Changed);
+            pragma Assert (Node_Valid (Before, Node));
+            pragma Assert (Node_Valid (After, Node));
+         end if;
+
+         pragma Loop_Invariant
+           (for all I in 1 .. Node =>
+              (if I /= Changed / 2 then Node_Valid (After, I)));
+      end loop;
+   end Lemma_Recomputed_Frame;
+
+   procedure Refresh_Path (H : in out Heap; Changed : Tree_Index)
+     with Pre  => H.Capacity > 0
+                  and then Changed <= 2 * H.Capacity - 1
+                  and then Valid_Except (H, Changed / 2),
+          Post => Is_Heap (H)
+                  and H.Last = H.Last'Old
+                  and H.Keys = H.Keys'Old;
+
+   procedure Refresh_Path (H : in out Heap; Changed : Tree_Index) is
+      Node   : Tree_Index := Changed;
+      Before : Heap := H with Ghost;
+   begin
+      while Node > 1 loop
+         declare
+            Parent : constant Index := Node / 2;
+         begin
+            Before := H;
+            Recompute (H, Parent);
+            Lemma_Recomputed_Frame (Before, H, Parent);
+            Node := Parent;
+         end;
+
+         pragma Loop_Invariant (Node <= 2 * H.Capacity - 1);
+         pragma Loop_Invariant (Valid_Except (H, Node / 2));
+         pragma Loop_Invariant (H.Last = H.Last'Loop_Entry);
+         pragma Loop_Invariant (H.Keys = H.Keys'Loop_Entry);
+         pragma Loop_Variant (Decreases => Node);
+      end loop;
+   end Refresh_Path;
+
+   procedure Lemma_Leaf_Changed
+     (Before, After : Heap; Leaf : Tree_Index)
+     with Ghost,
+          Pre  => Is_Heap (Before)
+                  and then Before.Capacity = After.Capacity
+                  and then After.Capacity > 0
+                  and then Leaf in After.Capacity .. 2 * After.Capacity - 1
+                  and then Before.Winners = After.Winners
+                  and then Before.Winner_Keys = After.Winner_Keys
+                  and then
+                    (for all Node in After.Capacity .. 2 * After.Capacity - 1 =>
+                       (if Node /= Leaf then
+                          Position_At (After, Node) = Position_At (Before, Node)
+                          and then
+                            (if Position_At (After, Node) > 0 then
+                               Key_At (After, Node) = Key_At (Before, Node)))),
+          Post => Valid_Except (After, Leaf / 2);
+
+   procedure Lemma_Leaf_Changed
+     (Before, After : Heap; Leaf : Tree_Index)
+   is
+   begin
+      for Node in 1 .. After.Capacity - 1 loop
+         if Node /= Leaf / 2 then
+            pragma Assert (2 * Node /= Leaf);
+            pragma Assert (2 * Node + 1 /= Leaf);
+            pragma Assert (Node_Valid (Before, Node));
+            pragma Assert (Node_Valid (After, Node));
+         end if;
+
+         pragma Loop_Invariant
+           (for all I in 1 .. Node =>
+              (if I /= Leaf / 2 then Node_Valid (After, I)));
+      end loop;
+   end Lemma_Leaf_Changed;
+
+   procedure Restore_Leaf
+     (H : in out Heap; Before : Heap; Leaf : Tree_Index)
+     with Pre  => Is_Heap (Before)
+                  and then Before.Capacity = H.Capacity
+                  and then H.Capacity > 0
+                  and then Leaf in H.Capacity .. 2 * H.Capacity - 1
+                  and then Before.Winners = H.Winners
+                  and then Before.Winner_Keys = H.Winner_Keys
+                  and then
+                    (for all Node in H.Capacity .. 2 * H.Capacity - 1 =>
+                       (if Node /= Leaf then
+                          Position_At (H, Node) = Position_At (Before, Node)
+                          and then
+                            (if Position_At (H, Node) > 0 then
+                               Key_At (H, Node) = Key_At (Before, Node)))),
+          Post => Is_Heap (H)
+                  and H.Last = H.Last'Old
+                  and H.Keys = H.Keys'Old;
+
+   procedure Restore_Leaf
+     (H : in out Heap; Before : Heap; Leaf : Tree_Index)
+   is
+   begin
+      Lemma_Leaf_Changed (Before, H, Leaf);
+      Refresh_Path (H, Leaf);
+   end Restore_Leaf;
+
+   procedure Build (H : in out Heap)
+     with Post => Is_Heap (H)
+                  and H.Last = H.Last'Old
+                  and H.Keys = H.Keys'Old;
+
+   procedure Build (H : in out Heap) is
+   begin
+      for Node in reverse 1 .. H.Capacity - 1 loop
+         Recompute (H, Node);
+
+         pragma Loop_Invariant
+           (for all I in Node .. H.Capacity - 1 => Node_Valid (H, I));
+         pragma Loop_Invariant (H.Last = H.Last'Loop_Entry);
+         pragma Loop_Invariant (H.Keys = H.Keys'Loop_Entry);
+      end loop;
+   end Build;
+
+   procedure Lemma_Parent_Beats_Child
+     (H : Heap; Parent : Index; Child : Tree_Index)
+     with Ghost,
+          Pre  => Parent < H.Capacity
+                  and then Child in 2 * Parent .. 2 * Parent + 1
+                  and then Position_At (H, Child) > 0
+                  and then Node_Valid (H, Parent),
+          Post => Position_At (H, Parent) > 0
+                  and then Key_At (H, Parent) <= Key_At (H, Child);
+
+   procedure Lemma_Parent_Beats_Child
+     (H : Heap; Parent : Index; Child : Tree_Index) is null;
+
+   procedure Lemma_Root_Is_Minimum (H : Heap)
+     with Ghost,
+          Pre  => not Is_Empty (H) and then Is_Heap (H),
+          Post => Is_Minimum (H, Peek_Min (H));
+
+   procedure Lemma_Root_Is_Minimum (H : Heap) is
+      Node : Tree_Index;
+   begin
+      for I in 1 .. H.Last loop
+         Node := Leaf_Node (H, I);
+
+         while Node > 1 loop
+            Lemma_Parent_Beats_Child (H, Node / 2, Node);
+            Node := Node / 2;
+
+            pragma Loop_Invariant (Node <= 2 * H.Capacity - 1);
+            pragma Loop_Invariant (Position_At (H, Node) > 0);
+            pragma Loop_Invariant (Key_At (H, Node) <= H.Keys (I));
+            pragma Loop_Variant (Decreases => Node);
+         end loop;
+
+         pragma Loop_Invariant
+           (for all J in 1 .. I => Peek_Min (H) <= H.Keys (J));
+      end loop;
+   end Lemma_Root_Is_Minimum;
+
+   procedure Lemma_Root_Represents_Key (H : Heap)
+     with Ghost,
+          Pre  => not Is_Empty (H) and then Is_Heap (H),
+          Post => Root_Position (H) <= H.Last
+                  and then Peek_Min (H) = H.Keys (Root_Position (H));
+
+   procedure Lemma_Root_Represents_Key (H : Heap) is
+      Node : Tree_Index := 1;
+   begin
+      if H.Capacity = 1 then
+         return;
+      end if;
+
+      while Node < H.Capacity loop
+         declare
+            Left  : constant Tree_Index := 2 * Node;
+            Right : constant Tree_Index := Left + 1;
+         begin
+            if Position_At (H, Left) = Position_At (H, Node)
+              and then Position_At (H, Left) > 0
+              and then Key_At (H, Left) = Key_At (H, Node)
+            then
+               Node := Left;
+            else
+               pragma Assert (Position_At (H, Right) = Position_At (H, Node));
+               pragma Assert (Position_At (H, Right) > 0);
+               pragma Assert (Key_At (H, Right) = Key_At (H, Node));
+               Node := Right;
+            end if;
+         end;
+
+         pragma Loop_Invariant (Node <= 2 * H.Capacity - 1);
+         pragma Loop_Invariant (Position_At (H, Node) = H.Winners (1));
+         pragma Loop_Invariant (Position_At (H, Node) > 0);
+         pragma Loop_Invariant (Key_At (H, Node) = H.Winner_Keys (1));
+         pragma Loop_Variant (Increases => Node);
+      end loop;
+
+      pragma Assert (Position_At (H, Node) = Node - H.Capacity + 1);
+      pragma Assert (Key_At (H, Node) = H.Keys (Root_Position (H)));
+   end Lemma_Root_Represents_Key;
+
+   procedure Clear (H : in out Heap) is
+   begin
+      H.Last := 0;
+      Build (H);
+   end Clear;
+
+   function Peek_Min (H : Heap) return Key_Type is
+   begin
+      Lemma_Root_Is_Minimum (H);
+      Lemma_Root_Represents_Key (H);
+      return (if H.Capacity = 1 then H.Keys (1) else H.Winner_Keys (1));
+   end Peek_Min;
+
+   function Root_Position (H : Heap) return Index is
+   begin
+      Lemma_Root_Represents_Key (H);
+      return (if H.Capacity = 1 then 1 else H.Winners (1));
+   end Root_Position;
+
+   function Min_Of (H : Heap) return Key_Type is
+      Result : Key_Type := H.Keys (1);
+   begin
+      for I in 2 .. H.Last loop
+         if H.Keys (I) < Result then
+            Result := H.Keys (I);
+         end if;
+
+         pragma Loop_Invariant (for all J in 1 .. I => Result <= H.Keys (J));
+         pragma Loop_Invariant
+           (for some J in 1 .. I => Result = H.Keys (J));
+      end loop;
+      return Result;
+   end Min_Of;
+
+   procedure Insert (H : in out Heap; K : Key_Type) is
+      Before : constant Heap := H with Ghost;
+      Keys_0 : constant Key_Array := H.Keys with Ghost;
+      Slot   : constant Index := H.Last + 1;
+      Leaf   : constant Tree_Index := Leaf_Node (H, Slot);
+   begin
+      H.Keys (Slot) := K;
+      H.Last := Slot;
+
+      Restore_Leaf (H, Before, Leaf);
+
+      Models.Lemma_Same_Prefix (Keys_0, H.Keys, H.Last - 1);
+      Models.Lemma_Add_Congruent
+        (Models.Occurrences (Keys_0, H.Last - 1),
+         Models.Occurrences (H.Keys, H.Last - 1), K);
+   end Insert;
+
+   procedure Meld (Into : in out Heap; From : in out Heap) is
+      Before : constant Key_Array := Into.Keys with Ghost;
+      Base   : constant Extended_Index := Into.Last;
+      Prev   : Key_Array (1 .. Into.Capacity) with Ghost;
+   begin
+      for I in 1 .. From.Last loop
+         Prev := Into.Keys;
+         Into.Keys (Base + I) := From.Keys (I);
+         Into.Last := Base + I;
+
+         Models.Lemma_Same_Prefix (Prev, Into.Keys, Base + I - 1);
+         Models.Lemma_Add_Congruent
+           (Models.Occurrences (Prev, Base + I - 1),
+            Models.Occurrences (Into.Keys, Base + I - 1), From.Keys (I));
+         Models.Lemma_Sum_Add
+           (Models.Occurrences (Before, Base),
+            Models.Occurrences (From.Keys, I - 1), From.Keys (I));
+         Models.Lemma_Sum_Empty (Models.Occurrences (Before, Base));
+
+         pragma Loop_Invariant (Into.Last = Base + I);
+         pragma Loop_Invariant
+           (for all J in 1 .. Base => Into.Keys (J) = Before (J));
+         pragma Loop_Invariant
+           (Model (Into) = Models.Occurrences (Before, Base)
+                          + Models.Occurrences (From.Keys, I));
+      end loop;
+
+      if From.Last = 0 then
+         Models.Lemma_Sum_Empty (Models.Occurrences (Before, Base));
+      end if;
+
+      Build (Into);
+      From.Last := 0;
+      Build (From);
+   end Meld;
+
+   procedure Extract_Min (H : in out Heap; K : out Key_Type) is
+      Old_H  : constant Heap := H with Ghost;
+      Before : Heap := H with Ghost;
+      Keys_0 : constant Key_Array := H.Keys with Ghost;
+      Slot   : constant Index := Root_Position (H);
+      Last   : constant Index := H.Last;
+      Moved  : constant Key_Type := H.Keys (Last);
+      Leaf   : Tree_Index;
+   begin
+      Lemma_Root_Is_Minimum (H);
+      Lemma_Root_Represents_Key (H);
+      K := Peek_Min (H);
+
+      H.Keys (Slot) := Moved;
+      Leaf := Leaf_Node (H, Slot);
+      Restore_Leaf (H, Before, Leaf);
+
+      Before := H;
+      H.Last := H.Last - 1;
+      Leaf := Leaf_Node (H, Last);
+      Restore_Leaf (H, Before, Leaf);
+
+      if Slot < Last then
+         Models.Lemma_Set (Keys_0, H.Keys, Slot, Last - 1);
+         Models.Lemma_Add_Congruent
+           (Models.Occurrences (H.Keys, Last - 1),
+            Models.Occurrences (Old_H.Keys, Last - 1), K);
+         Models.Lemma_Add_Commutes
+           (Models.Occurrences (Old_H.Keys, Last - 1), K, Moved);
+         Models.Lemma_Add_Cancels
+           (Models.Occurrences (Old_H.Keys, Last),
+            KM.Add (Models.Occurrences (H.Keys, Last - 1), K), Moved);
+      end if;
+   end Extract_Min;
+
+end Heaps.Tournament;

